using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Note-taking store (in-memory) ---
var notes = new List<string>();

// --- Tool definitions ---

[Description("Search the web for information on a query. Returns a list of result snippets.")]
async Task<string> SearchWeb(
    [Description("The search query string")] string query)
{
    Console.ForegroundColor = ConsoleColor.DarkYellow;
    Console.WriteLine($"  🔍 Searching: \"{query}\"");
    Console.ResetColor();

    try
    {
        using var http = new HttpClient();
        http.DefaultRequestHeaders.UserAgent.ParseAdd(
            "ResearchAgent/1.0 (compatible; bot)");

        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
        var json = await http.GetStringAsync(url);
        using var doc = JsonDocument.Parse(json);

        var results = new List<string>();

        // Abstract / instant answer
        var abstractText = doc.RootElement.GetProperty("AbstractText").GetString();
        var abstractSource = doc.RootElement.GetProperty("AbstractSource").GetString();
        if (!string.IsNullOrWhiteSpace(abstractText))
            results.Add($"[{abstractSource}] {abstractText}");

        // Related topics
        if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
        {
            foreach (var topic in topics.EnumerateArray().Take(5))
            {
                if (topic.TryGetProperty("Text", out var text) &&
                    !string.IsNullOrWhiteSpace(text.GetString()))
                {
                    var snippet = text.GetString()!;
                    results.Add(snippet);
                }
            }
        }

        if (results.Count == 0)
            return $"No results found for \"{query}\". Try rephrasing.";

        return string.Join("\n\n", results);
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}";
    }
}

[Description("Save a research note for later reference. Use this to record important findings.")]
string SaveNote(
    [Description("The note content to save")] string note)
{
    notes.Add(note);
    Console.ForegroundColor = ConsoleColor.DarkCyan;
    Console.WriteLine($"  📝 Note saved ({notes.Count} total)");
    Console.ResetColor();
    return $"Note saved. You now have {notes.Count} note(s).";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";

    return string.Join("\n---\n",
        notes.Select((n, i) => $"Note {i + 1}: {n}"));
}

// --- Build the AI client with tools ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new[]
{
    AIFunctionFactory.Create(SearchWeb),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

var systemPrompt = """
    You are a research agent. Your job is to research a topic the user provides by:
    1. Searching the web for relevant information (make multiple searches to cover different angles).
    2. Saving important findings as notes using the note-taking tool.
    3. After thorough research, retrieving your notes and producing a well-organized summary.

    Always search from at least 2-3 different angles, save key facts as notes,
    then compile a final summary. Be thorough but concise.
    """;

// --- Interactive loop ---

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        🔬  AI Research Agent  🔬        ║");
Console.WriteLine("╠══════════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Green;
    Console.Write("Research topic: ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notes.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
    };

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching... (tool calls will appear below)");
    Console.ResetColor();

    var response = await client.GetResponseAsync(messages, chatOptions);

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.White;
    Console.WriteLine("═══ Research Summary ═══");
    Console.ResetColor();
    Console.WriteLine(response.Text);
    Console.WriteLine();
}

